// Merge webhook body fields with extracted PDF text
const webhookBody = $('SGB Extract Webhook').item.json.body;
const pdfText = $json.text || $json.data || '';

return {
  ...webhookBody,
  pdf_text: pdfText
};

const root = $json;

function deepValue(obj, path) {
  return path.split('.').reduce((acc, key) => acc && acc[key], obj);
}

function collectNamedArrays(value, found = []) {
  if (!value || typeof value !== 'object') return found;
  if (Array.isArray(value.questions)) found.push(value.questions);
  if (Array.isArray(value.urlParameters)) found.push(value.urlParameters);
  if (Array.isArray(value.calculations)) found.push(value.calculations);
  if (Array.isArray(value)) {
    for (const item of value) collectNamedArrays(item, found);
  } else {
    for (const item of Object.values(value)) collectNamedArrays(item, found);
  }
  return found;
}

const fields = {};
for (const list of collectNamedArrays(root)) {
  for (const item of list) {
    if (!item || !item.name) continue;
    fields[String(item.name).trim()] = item.value ?? '';
  }
}

function get(...keys) {
  for (const key of keys) {
    const direct = root[key];
    const body = root.body?.[key];
    const field = fields[key];
    const nested = key.includes('.') ? deepValue(root, key) : undefined;
    const values = [direct, body, field, nested];
    for (const value of values) {
      if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim();
    }
  }
  return '';
}

function cleanNumber(value) {
  return String(value ?? '')
    .replace(/[₹,%]/g, '')
    .replace(/,/g, '')
    .trim();
}

function titleCase(value) {
  return String(value || '').trim().replace(/\s+/g, ' ');
}

function monthNumber(mon) {
  const key = String(mon || '').slice(0, 3).toLowerCase();
  return { jan: '01', feb: '02', mar: '03', apr: '04', may: '05', jun: '06', jul: '07', aug: '08', sep: '09', oct: '10', nov: '11', dec: '12' }[key] || '';
}

function normalizeDate(value) {
  const text = String(value || '').trim();
  if (!text) return '';
  const iso = text.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/);
  if (iso) return `${iso[1]}-${String(iso[2]).padStart(2, '0')}-${String(iso[3]).padStart(2, '0')}`;
  const dmyMon = text.match(/(\d{1,2})[\-\s]([A-Za-z]{3,9})[\-\s](\d{4})/i);
  if (dmyMon) {
    const mm = monthNumber(dmyMon[2]);
    if (mm) return `${dmyMon[3]}-${mm}-${String(dmyMon[1]).padStart(2, '0')}`;
  }
  const parsed = new Date(text);
  if (!Number.isNaN(parsed.getTime())) return parsed.toISOString().slice(0, 10);
  return text;
}

function findText(patterns, fallback = '') {
  const pdfText = get('pdf_text', 'text', 'extracted_text', 'body.pdf_text', 'body.text');
  const text = String(pdfText || '').replace(/\r/g, '\n');
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match?.[1]) return titleCase(match[1]);
  }
  return fallback;
}

const fileName = get('certificate_file_name', 'file_name', 'filename', 'name');
if (fileName && !/^NSCL\d{13}\.pdf$/i.test(fileName)) {
  throw new Error(`Ignored non-standard SGB filename: ${fileName}. Expected NSCL2023004979591.pdf`);
}

const spreadsheetId = get('spreadsheet_id', 'spreadsheetId', 'Spreadsheet ID');
if (!spreadsheetId) throw new Error(`Missing spreadsheet_id. Received keys: ${Object.keys(root).join(', ')}; named fields: ${Object.keys(fields).join(', ')}`);

const certificateNumber = get('certificate_number') || findText([/Certificate\s*(?:No\.?|Number)\s*[:\-]?\s*([A-Z0-9]+)/i]);
const investorId = get('investor_id') || findText([/Investor\s*ID\s*[:\-]?\s*([0-9]+)/i], fileName.match(/^NSCL(\d{13})\.pdf$/i)?.[1] || '');
const registeredHolder = get('registered_holder') || findText([
  /Registered\s*Holder\s*[:\-]?\s*([^\n]+)/i,
  /Name\s*of\s*Investor\s*[:\-]?\s*([^\n]+)/i,
  /(?:Holder|Investor|Name)\s*:\s*([A-Z][A-Z\s]+)/
]);
const schemeYear = get('scheme_year') || findText([
  /Scheme\s*Year\s*[:\-]?\s*([0-9]{4}[\-–][0-9]{2,4})/i,
  /SGB\s*([0-9]{4}[\-–][0-9]{2,4})/i,
  /Series\s*[IVX]+\s*([0-9]{4}[\-–][0-9]{2,4})/i
]);
const holdingUnits = cleanNumber(get('holding_units') || findText([
  /Holding\s*Units\s*[:\-]?\s*([0-9.]+)/i,
  /No\.?\s*of\s*Units\s*[:\-]?\s*([0-9.]+)/i,
  /Units\s*[:\-]?\s*([0-9.]+)/i,
  /Quantity\s*[:\-]?\s*([0-9.]+)/i
]));
const issueDate = normalizeDate(get('issue_date') || findText([
  /Issue\s*Date\s*[:\-]?\s*([0-9]{1,2}[\-\s][A-Za-z]{3,9}[\-\s][0-9]{4})/i,
  /Date\s*of\s*Issue\s*[:\-]?\s*([0-9]{1,2}[\-\s][A-Za-z]{3,9}[\-\s][0-9]{4})/i,
  /Issued\s*On\s*[:\-]?\s*([0-9]{1,2}[\-\s][A-Za-z]{3,9}[\-\s][0-9]{4})/i
]));
const maturityDate = normalizeDate(get('maturity_date') || findText([
  /Maturity\s*Date\s*[:\-]?\s*([0-9]{1,2}[\-\s][A-Za-z]{3,9}[\-\s][0-9]{4})/i,
  /Date\s*of\s*Maturity\s*[:\-]?\s*([0-9]{1,2}[\-\s][A-Za-z]{3,9}[\-\s][0-9]{4})/i,
  /Matures\s*On\s*[:\-]?\s*([0-9]{1,2}[\-\s][A-Za-z]{3,9}[\-\s][0-9]{4})/i
]));
const interestRatePct = cleanNumber(get('interest_rate_pct') || findText([/Interest\s*(?:Rate)?\s*[:\-]?\s*([0-9.]+)\s*%/i], '2.5'));
const initialInvestment = cleanNumber(get('initial_investment') || findText([
  /(?:Initial\s*)?Investment\s*(?:Amount)?\s*[:\u20B9\- ]+([0-9,]+(?:\.[0-9]+)?)/i,
  /Amount\s*(?:Paid|Invested)\s*[:\u20B9\- ]+([0-9,]+(?:\.[0-9]+)?)/i,
  /Total\s*Amount\s*[:\u20B9\- ]+([0-9,]+(?:\.[0-9]+)?)/i
]));
const issuePricePerUnit = holdingUnits && initialInvestment
  ? String(Math.round((Number(initialInvestment) / Number(holdingUnits)) * 100) / 100)
  : cleanNumber(get('issue_price_per_unit') || findText([
      /Issue\s*Price\s*(?:per\s*(?:Unit|Gram))?\s*[:\u20B9\- ]+([0-9,]+(?:\.[0-9]+)?)/i,
      /Price\s*per\s*(?:Unit|Gram)\s*[:\u20B9\- ]+([0-9,]+(?:\.[0-9]+)?)/i
    ]));

// Determine extraction status — extracted if we got at least 3 key fields from PDF
const pdfFieldsFound = [certificateNumber, registeredHolder, schemeYear, holdingUnits, issueDate, maturityDate, initialInvestment]
  .filter(v => v && v.trim() !== '').length;
const extractionStatus = pdfFieldsFound >= 3 ? 'extracted' : pdfFieldsFound > 0 ? 'partial' : 'needs_review';

return {
  spreadsheet_id: spreadsheetId,
  tab_name: get('tab_name') || 'SGB',
  customer_id: get('customer_id'),
  entry_date: get('entry_date') || new Date().toISOString().slice(0, 10),
  certificate_file_name: fileName,
  certificate_drive_file_id: get('certificate_drive_file_id', 'file_id', 'drive_file_id'),
  certificate_drive_url: get('certificate_drive_url', 'file_url', 'drive_file_url'),
  certificate_number: certificateNumber,
  investor_id: investorId,
  registered_holder: registeredHolder,
  issuer: get('issuer') || 'Government of India',
  scheme_name: get('scheme_name') || 'SOVEREIGN GOLD BONDS SCHEME',
  scheme_year: schemeYear,
  holding_units: holdingUnits,
  issue_date: issueDate,
  maturity_date: maturityDate,
  interest_rate_pct: interestRatePct || '2.5',
  interest_payout_frequency: get('interest_payout_frequency') || 'Half yearly',
  interest_payout_month_1: get('interest_payout_month_1') || 'June 28',
  interest_payout_month_2: get('interest_payout_month_2') || 'December 28',
  initial_investment: initialInvestment,
  issue_price_per_unit: issuePricePerUnit,
  purchase_channel: get('purchase_channel') || 'Bank / Broker',
  broker_company: get('broker_company'),
  broker_poc_name: get('broker_poc_name'),
  broker_phone: get('broker_phone'),
  broker_email: get('broker_email'),
  extraction_status: extractionStatus,
  notes: get('notes')
};
